const entries=JSON.parse(read('gates/test-intent/.changesets/upgrade-retire.md').split('```json\n')[1].split('\n```')[0]).entries;
const afterIds=json('tmp/builder/step7/gradle-method-identities.json');
const beforeIds=json('tmp/builder/step7/before-gradle-method-identities.json');
const afterDir='tmp/builder/resume-20261025/old-results/indexer-worker/test';
const beforeFresh='tmp/builder/step7/before-results/test';
const manifests=json('tmp/builder/evidence/final-candidate-files.json');
const allIds=[...new Set([2,3,5,6].flatMap(i=>entries[i].newChecks))];
const classOf=id=>'io.justsearch.indexerworker.server.'+path.basename(checkFile(id),'.java');
const newMethodsFor=cl=>new Set(allIds.filter(x=>classOf(x)===cl).map(checkName));
const artifacts=new Map();
function artifact(p){let v=artifacts.get(p);if(!v){const bytes=fs.readFileSync(path.join(root,p));v={path:p,sha256:sha(bytes),bytes:bytes.length};artifacts.set(p,v);}return v;}
function mappedCases(xmlPath,identitySet=null,restrictMethods=null){
 const text=read(xmlPath);const raw=parseJUnitXml(text);const cl=raw[0]?.classname;
 let identities=identitySet?.[cl];
 if(identities && restrictMethods)identities=identities.filter(x=>restrictMethods.has(x.method));
 if(identities){assert(JSON.stringify(raw.map(x=>x.name))===JSON.stringify(identities.map(x=>x.displayName)),'Raw XML/Gradle identity sequence differs: '+xmlPath);}
 const mapped=raw.map((c,i)=>({...c,displayName:c.name,name:identities?identities[i].fullName:c.name,method:identities?identities[i].method:c.name.split('(')[0]}));
 return {cases:mapped,xml:artifact(xmlPath),suiteTimestamp:/\btimestamp="([^"]+)"/.exec(text)?.[1]??null,source:xmlPath};
}
function xmlFor(folder,id){return folder+'/TEST-'+classOf(id)+'.xml';}
function getAfter(id){
 if(id.includes('Release030RetirementHttpTest'))return mappedCases(xmlFor('tmp/builder/resume-20261025/remaining-results/indexer-worker/retirementHttpEvidence',id));
 return mappedCases(xmlFor(afterDir,id),afterIds);
}
function getBefore(id){
 const cl=classOf(id),methods=newMethodsFor(cl);
 if(id.includes('Release030RetirementSafetyTest')||id.includes('Release030UpgradeProbeTest'))return mappedCases(xmlFor(beforeFresh,id),beforeIds);
 if(id.includes('Release030RetirementHttpTest'))return mappedCases(xmlFor('tmp/builder/step7/before-results/retirementHttpEvidence',id));
 let folder;
 if(id.includes('Release030RecoveryShutdownTest'))folder='tmp/builder/evidence/before-shutdown-control-results';
 else if(id.includes('Release030RetirementCompletedBuildTest'))folder='tmp/builder/evidence/before-final-completed-markers-results';
 else if(id.includes('Release030MigrationRetirementTest')||id.includes('Release030RetirementBudgetTest'))folder='tmp/builder/evidence/before-adapted-controls-results';
 else if(/Release030(ExactFileRecovery|ReplayRetention|AdmissionDebt|ChallengerRecovery)Test/.test(id))folder='tmp/builder/evidence/before-native-final-results';
 else folder='tmp/builder/evidence/before-final-complete-results/test';
 // Old preservation subsets contain exactly the declared methods, as verified against the
 // preserved final Gradle binary leaf identities and the entire ordered XML leaf sequence.
 const subset=/Release030(ExactFileRecovery|ReplayRetention|AdmissionDebt|ChallengerRecovery)Test/.test(id);
 return mappedCases(xmlFor(folder,id),afterIds,subset?methods:null);
}
function selected(bundle,id){const method=checkName(id);return bundle.cases.filter(c=>c.method===method);}
const checkFiles=[...new Set(allIds.map(checkFile))];
const helperPaths=manifests.files.filter(x=>x.path.includes('/src/test/')).map(x=>x.path);
