for(const p of new Set([...checkFiles,...helperPaths])){const source=blob(frozen,p);assert(source!==null,'Missing frozen source '+p);assert(contentDigest(source)===contentDigest(read(p)),'Check/helper changed since frozen execution: '+p);frozenSources[p]={executionContentDigest:contentDigest(source),currentContentDigest:contentDigest(read(p)),materializedSnapshot:frozen};}
