fs.writeFileSync(path.join(root,supportPath),JSON.stringify(support,null,2)+'\n');
const patch=git('diff','--binary','--unified=0',execution,frozen,'--',...helperPaths);fs.writeFileSync(path.join(root,'gates/test-intent/evidence/upgrade-retire-frozen-tests.patch'),patch);
const oldCommand=json('tmp/builder/evidence/after-final-complete-verification-command.json');
const freshBeforeCommand=json('tmp/builder/step7/before-command.json');
const httpCommand=json('tmp/builder/resume-20261025/remaining-command.json');
function command(x){return (x.argv??x.command).map(v=>JSON.stringify(v)).join(' ');}
const reports=[];
for(const i of [2,3,5,6]){
 const entry=entries[i],checks=[],beforeChecks=[],beforeRuns=[];
 for(const id of entry.newChecks){
  const a=getAfter(id),ac=selected(a,id),b=getBefore(id),bc=selected(b,id);
  assert(ac.length>0&&bc.length>0,'Unselected check '+id);
  const outcome=summarize(ac),beforeOutcome=summarize(bc);
  assert(outcome.executed&&!outcome.skipped&&outcome.outcome==='passed','Frozen after did not pass '+id);
  const fb=classifyFailBefore({runner:'gradle',cases:bc});
  if(entry.repaired)assert(fb.classification==='assertion','Not an actual assertion fail-before '+id+': '+fb.classification);
  else assert(beforeOutcome.executed&&!beforeOutcome.skipped&&beforeOutcome.outcome==='passed','Preservation before did not pass '+id);
  checks.push({id,file:checkFile(id),runner:'gradle',contentDigest:contentDigest(read(checkFile(id))),...outcome,cases:ac,executionScope:'completed frozen-source execution, not current integrated behavior',rawXml:a.xml,suiteTimestamp:a.suiteTimestamp});
  beforeChecks.push({id,...fb,...(!entry.repaired?{purpose:'preservation control',outcome:beforeOutcome.outcome}:{}),cases:bc,rawXml:b.xml,suiteTimestamp:b.suiteTimestamp});
  beforeRuns.push({command:'node tmp/builder/step7/collect-upgrade-d4.mjs',kind:'documented artifact collection',xml:b.xml,originalExecutionCommand:b.source.startsWith('tmp/builder/step7/')?command(freshBeforeCommand):null,originalArgvProvenance:b.source.startsWith('tmp/builder/step7/')?'before-command.json records exact fresh argv':'Original full argv was not retained for this selected historical before run; raw XML, execution log, same-source overlay and source manifests are retained. This collector command is not presented as its Gradle command.'});
 }
 const producerText=read('tmp/builder/step7/collect-upgrade-d4.mjs');
 const ev={schema:EVIDENCE_SCHEMA,producer:{script:EVIDENCE_PRODUCER,scriptDigest:contentDigest(read(EVIDENCE_PRODUCER)),adaptation:{actualProducer:'tmp/builder/step7/collect-upgrade-d4.mjs',actualProducerDigest:contentDigest(producerText),identityDecoder:'tmp/builder/step7/read-gradle-identities.py',identityDecoderDigest:contentDigest(read('tmp/builder/step7/read-gradle-identities.py')),mode:'Read actual completed preserved XML/binary executions. Canonical runner not invoked; this is an explicitly adapted collection envelope, not a claim that canonical run-evidence executed these tests.'}},createdAt:new Date().toISOString(),revision:execution,tree:support.frozenSourceGitTree,environment:{kind:'artifact-collection environment, not old execution JVM identity',platform:process.platform,arch:process.arch,node:process.version,originalExecutionEnvironment:artifact('tmp/builder/evidence/reproduction/environment.json'),originalAfterHarness:artifact('tmp/builder/evidence/reproduction/test-jvm-after.gradle')},runs:[{command:command(oldCommand),kind:'original frozen command',commandArtifact:artifact('tmp/builder/evidence/after-final-complete-verification-command.json'),completion:'Named indexer-worker suites completed; outer program later interrupted inside downstream app-engine. Global exit is not relabelled passed.'},...(checks.some(c=>c.id.includes('HttpTest'))?[{command:command(httpCommand),kind:'original step6 exact frozen-package HTTP command',commandArtifact:artifact('tmp/builder/resume-20261025/remaining-command.json'),completion:'HTTP check completed; global build exit 1 was UI discovery failure'}]:[])],checks,failBefore:{revision:execution,purpose:entry.repaired?'assertion fail-before':'preservation before',runs:beforeRuns,checks:beforeChecks},sourceBindings:{path:supportPath,sha256:sha(read(supportPath))},scope:{after:'immutable frozen code represented by d9663d16, executed with HEAD 8292 and original dirty manifest',currentCollector:integrated,integratedProductionChanges:dependencyChanges.length,notFreshCurrentIntegratedBehavior:true,acceptanceAuthored:false}};
 ev.digest=evidenceSelfDigest(ev);fs.writeFileSync(path.join(root,entry.evidence),JSON.stringify(ev,null,2)+'\n');
 const counts={entry:i+1,artifact:entry.evidence,checks:checks.length,afterCases:checks.reduce((n,c)=>n+c.cases.length,0),beforeCases:beforeChecks.reduce((n,c)=>n+c.cases.length,0),beforeClassification:entry.repaired?'assertion failures':'preserved passes'};reports.push(counts);console.log(counts);
}
const producerEnvelope={schema:'upgrade-retire-adapted-producer.v1',command:'node tmp/builder/step7/collect-upgrade-d4.mjs',canonicalEnvelopeCompatibilityOnly:true,producerSource:read('tmp/builder/step7/collect-upgrade-d4.mjs'),producerSourceDigest:contentDigest(read('tmp/builder/step7/collect-upgrade-d4.mjs')),identityDecoderSource:read('tmp/builder/step7/read-gradle-identities.py'),identityDecoderDigest:contentDigest(read('tmp/builder/step7/read-gradle-identities.py')),rawBinary:artifact(afterDir+'/binary/results-generic.bin'),beforeRawBinary:artifact(beforeFresh+'/binary/results-generic.bin'),caseIdentityRule:'Decode Gradle Kryo string triples, bind full method identity to exact XML leaf display names and ordinal, require equality of the whole leaf sequence; no result-status filtering. Historical native subsets must equal the complete declared-method subsequence.',reports,knownLimits:['Historical before argv for unchanged preserved runs is unavailable; never invented. Actual collector invocation, raw XML, full after command, fresh Safety/Probe/HTTP command, same-source overlay and original source manifests are bound.','Frozen production/build inputs differ from current integrated main; no fresh integrated recovery result or acceptance is claimed.']};
fs.writeFileSync(path.join(root,'gates/test-intent/evidence/upgrade-retire-producer.json'),JSON.stringify(producerEnvelope,null,2)+'\n');
fs.writeFileSync(path.join(here,'d4-collection-report.json'),JSON.stringify({reports,artifacts:[...artifacts.values()]},null,2)+'\n');

