from pathlib import Path
import re,json,sys,xml.etree.ElementTree as E

def read_string(b,p):
 first=b[p];p+=1
 if not first&128:
  out=bytearray([first])
  while not out[-1]&128:
   out.append(b[p]);p+=1
  out[-1]&=127
  return out.decode('utf8'),p
 size=first&63
 if first&64:
  shift=6
  while True:
   n=b[p];p+=1;size|=(n&127)<<shift
   if not n&128:break
   shift+=7
   if shift>32:raise ValueError('bad length')
 if size<=1:return (None if size==0 else ''),p
 chars=[]
 for i in range(size-1):
  n=b[p];ln=1 if n<128 else 2 if n<224 else 3 if n<240 else 4
  chars.append(b[p:p+ln].decode('utf8'));p+=ln
 return ''.join(chars),p

def identities(folder):
 b=(folder/'binary/results-generic.bin').read_bytes();records={};seen=set()
 for hit in re.finditer(rb'[A-Za-z_$][A-Za-z0-9_$]{4,}\(',b):
  for offset in range(0,7):
   p=hit.start()-offset
   if p<0:continue
   try:
    full,p2=read_string(b,p)
    if not full or not re.match(r'^[A-Za-z_$][\w$]*\([^\x00]*\)(\[\d+\])?$',full) or len(full)>500:continue
    display,p3=read_string(b,p2);cl,p4=read_string(b,p3)
    if not cl or not re.match(r'^io\.justsearch\.[\w.$]+$',cl):continue
    key=(hit.start(),full,display,cl)
    if key not in seen:records.setdefault(cl,[]).append({'offset':hit.start(),'method':full.split('(')[0],'fullName':full,'displayName':display if display is not None else full});seen.add(key)
    break
   except (ValueError,IndexError,UnicodeError):pass
 for cl,v in records.items():
  v.sort(key=lambda x:x['offset'])
  xml=folder/('TEST-'+cl+'.xml')
  if xml.exists():
   from collections import Counter
   remaining=Counter(c.get('name') for c in E.parse(xml).getroot().findall('testcase'));leaves=[]
   for item in v:
    if remaining[item['displayName']]>0:leaves.append(item);remaining[item['displayName']]-=1
   assert not +remaining,(cl,remaining)
   records[cl]=leaves
 return records

if __name__=='__main__':
 folder=Path(sys.argv[1]);r=identities(folder);out={}
 for cl in ['Release030MigrationRetirementTest','Release030RetirementSafetyTest','Release030ExactFileRecoveryTest','Release030RetirementCrashTest','Release030AdmissionDebtTest','Release030ReplayRetentionTest']:
  fq='io.justsearch.indexerworker.server.'+cl;p=folder/('TEST-'+fq+'.xml');cases=E.parse(p).getroot().findall('testcase');v=r[fq];assert [c.get('name') for c in cases]==[x['displayName'] for x in v],(cl,len(cases),v)
  print(cl,len(v),sorted(set(x['method'] for x in v)));out[fq]=v
 Path('tmp/builder/step7/gradle-method-identities.json').write_text(json.dumps(r,indent=2)+'\n')
